CREATE PROCEDURE SP_VUE_DCYARN
AS
EXEC ('
Alter View Vue_DCYarn as select  x.id,x.ExporterName,x.ExporterAddress,x.Phone,x.TIN,x.CST,x.PAN,x.StateName,x.StateCode,x.GSTNo,x.Pname ,x.Paddress ,x.PPhone,x.PTIN,x.PCST,x.Ppan,x.PStatename,x.PStateCode,x.Pgstno ,x.Descr,x.DCNo ,x.dt, x.Deptname,sum(x.qty)as qty,x.UOM ,Mas_Hsn.HSNCode ,x.cost,case when isnull(x.StateCode,'''') = isnull(x.PstateCode,'''') then case WHEN  isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0) then Mas_HSN.NBPercL else Mas_HSN.NBPercH end else 0 end / 2 Rate1,case when isnull(x.StateCode,'''') = isnull(x.PstateCode,'''') then case WHEN isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0) then Mas_HSN.NBPercL else Mas_HSN.NBPercH end else  0 end /2 Rate2, case when isnull(x.StateCode,'''') <> isnull(x.PstateCode,'''')then case WHEN  isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0) then Mas_HSN.NBPercL else Mas_HSN.NBPercH end else  0 end / 2 Rate3, x.EWaybillNo,x.EWaybilldt , Sum(x.Amount) As Amount ,case when isnull(x.StateCode,'''') = isnull(x.PstateCode,'''') then case WHEN  isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0) then ((Mas_HSN.NBPercL/2) * (sum(x.Qty) * x.Cost)) / 100  else ((Mas_HSN.NBPercH/2) * (sum(x.Qty) * x.Cost)) / 100 end else 0 end Amount1,case when isnull(x.StateCode,'''') = isnull(x.PstateCode,'''') then case WHEN  isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0) then((Mas_HSN.NBPercL/2) * (sum(x.Qty) * x.Cost)) / 100 else((Mas_HSN.NBPercH/2) * (sum(x.Qty) * x.Cost)) / 100 end else 0 end Amount2,case when isnull(x.StateCode,'''') <> isnull(x.PstateCode,'''') then case WHEN  isnull(X.cost,0) < isnull(Mas_hsn.UnitRate,0)  then (Mas_HSN.NBPercL * (sum(x.Qty) * x.Cost)) / 100 else(Mas_HSN.NBPercH * (sum(x.Qty) * x.Cost)) / 100 end else 0 end Amount3, x.VName,x.Transmode ,x.Terms  from (SELECT     (select HSNId from Mas_HSNPce where pcestage=''Finished'')  HSNid,Trs_Pcs1.ID , Mas_Exporter.ExporterName, Convert(varchar,Mas_Exporter.ExporterAddress)ExporterAddress, Mas_Exporter.Phone, Mas_Exporter.TIN, Mas_Exporter.CST,Mas_Exporter.pan AS PAN, Mas_State.StateName ,Mas_State.StateCode ,Mas_Exporter.GSTNo ,Case When Trs_Pcs1.DelType = ''Unit Transfer'' Then Mas_Unit.ExporterName Else Mas_Party.Pname END as Pname,Case when Trs_Pcs1.DelType = ''Unit Transfer'' Then convert(varchar,Mas_Unit.ExporterAddress) Else convert(varchar,Mas_Party.Paddress) End as Paddress,case When Trs_Pcs1.DelType = ''Unit Transfer''Then Mas_Unit.Phone Else  Mas_Party.Phone END AS PPhone,case When Trs_Pcs1.DelType = ''Unit Transfer'' Then Mas_Unit.TIN Else  Mas_Party.TIN End as PTIN,Case  When Trs_Pcs1.DelType = ''Unit Transfer'' Then Mas_Unit.CST Else  Mas_Party.CST END AS PCST, Case When Trs_Pcs1.DelType = ''Unit Transfer''  Then Mas_Unit.Pan   Else  Mas_Party.Pan  END AS Ppan, Case When Trs_Pcs1.DelType = ''Unit Transfer'' Then Mas_state.StateName  Else  Mas_state2.StateName  END AS PStatename, Case  When Trs_Pcs1.DelType = ''Unit Transfer'' Then Mas_state.Statecode   Else  Mas_state2.StateCode   END AS PStateCode,Case When Trs_Pcs1.DelType = ''Unit Transfer''  Then  Mas_Unit.GSTNo   Else  Mas_Party.GSTNo   END AS Pgstno,RTRIM(CAST(OrderMas.Jobno AS varchar)) + ''/'' + OrderMas.Finyear + ''/'' +OrderMas.BuyOrdNo +''/''+   Trs_Pcs2.StyleNo  as Descr, RTRIM(CAST(Trs_Pcs1.DocNo AS varchar)) + ''/'' + Trs_Pcs1.Finyear AS DCNo,Trs_Pcs1.dtDCDate dt, Mas_Dept.Deptname ,Trs_Pcs2.Pcs Qty,  ''Pcs'' as UOM, Trs_Pcs1.Remark,convert(varchar,Mas_Terms.Terms)Terms,case when Pro_Prod_PartwiseRate.Rate > 0 then (Pro_Prod_PartwiseRate.Cost + Pro_Prod_PartwiseRate .Rate ) else case when Pro_Prod_PartwiseRate.JobWrkRate > 0 then ( Pro_Prod_PartwiseRate.Cost + Pro_Prod_PartwiseRate.JobWrkRate) else Pro_Prod_PartwiseRate.cost end end Cost,Trs_Pcs1.EWaybillNo , Trs_Pcs1.EWaybilldt, (Trs_Pcs2.Pcs * (case when Pro_Prod_PartwiseRate.Rate > 0 then (Pro_Prod_PartwiseRate.Cost + Pro_Prod_PartwiseRate .Rate ) else  case when Pro_Prod_PartwiseRate.JobWrkRate > 0 then ( Pro_Prod_PartwiseRate.Cost + Pro_Prod_PartwiseRate.JobWrkRate) else  Pro_Prod_PartwiseRate.cost end end))  Amount, Mas_Vehicle.VName,isnull(Trs_Pcs1.TransportationMode,'''')Transmode  FROM    dbo.Trs_Pcs1 Trs_Pcs1 INNER JOIN  dbo.Mas_Exporter Mas_Exporter ON Trs_Pcs1.Coycode = Mas_Exporter.ExpID LEFT OUTER JOIN  dbo.Mas_Party Mas_Party ON Trs_Pcs1.Party = Mas_Party.PID INNER JOIN dbo.Trs_Pcs2 Trs_Pcs2 ON Trs_Pcs1.ID = Trs_Pcs2.ID INNER JOIN dbo.OrderMas OrderMas ON Trs_Pcs1.Ordjobno = OrderMas.OrdId LEFT OUTER JOIN dbo.Mas_Buyer Mas_Buyer ON OrderMas.BuyerID = Mas_Buyer.BuyerID LEFT JOIN   dbo.OrdSizeMas OrdSizeMas ON Trs_Pcs1.Ordjobno = OrdSizeMas.OrdID AND Trs_Pcs2.SizeID = OrdSizeMas.SizeID left outer join Mas_RejectionType  on Mas_RejectionType.RejectionTypeId = Trs_Pcs1.RejectionTypeId left outer join Pro_Prod_PartwiseRate on  Pro_Prod_PartwiseRate.OrdID = Trs_Pcs1.Ordjobno and Pro_Prod_PartwiseRate.Styleno = Trs_Pcs2.StyleNo  and Pro_Prod_PartwiseRate.PartID  =Trs_Pcs2.PartID  LEFT OUTER JOIN  dbo.Mas_JobWrkComp Mas_JobWrkComp ON  Pro_Prod_PartwiseRate.WrkID =Mas_JobWrkComp.Id LEFT OUTER JOIN  dbo.Mas_Dept Mas_Dept  ON Mas_JobWrkComp.DeptId = Mas_Dept.DeptID INNER JOIN dbo.Mas_Color Mas_Color  ON Trs_Pcs2.ColID = Mas_Color.ColID INNER JOIN  dbo.Mas_Size Mas_Size ON  Trs_Pcs2.SizeID = Mas_Size.SizeID INNER JOIN  dbo.Mas_StyleDesc Mas_StyleDesc ON Trs_Pcs2.StyleID = Mas_StyleDesc.StyleID LEFT OUTER JOIN dbo.Mas_Terms  ON Mas_Dept.DC_TermCode = dbo.Mas_Terms.ID LEFT OUTER JOIN dbo.Mas_Part ON Trs_Pcs2.PartID = dbo.Mas_Part.PartID LEFT OUTER JOIN  dbo.Mas_Panel Mas_Panel  ON Trs_Pcs2.PanelID = Mas_Panel.PanelID LEFT OUTER JOIN  dbo.Mas_Exporter Mas_Unit ON Trs_Pcs1.ToCoyCode = Mas_Unit.ExpID LEFT OUTER JOIN Mas_User ON Trs_Pcs1.PreparedBy = Mas_User.UserCode  left outer join Mas_Vehicle on Trs_Pcs1.VehicleCode = Mas_Vehicle.Code left outer join dbo.Mas_state on Mas_State.Id = Mas_Exporter.Stateid left outer join dbo.Mas_state Mas_state2 on Mas_State2.Id = Mas_Party.Stateid  cross join Options )X left join Mas_HSN on Mas_hsn.id =x.HSNID  group by Descr ,X.ID,X.ExporterName,x.ExporterAddress,x.Phone,x.TIN,x.CST,x.PAN,x.StateName,x.StateCode,x.GSTNo,x.Pname ,x.Paddress ,x.PPhone,x.PTIN,x.PCST,x.Ppan,x.PStatename,x.PStateCode ,x.Pgstno ,x.Descr,x.DCNo ,x.dt, x.Deptname,x.UOM ,Mas_Hsn.HSNCode ,x.cost,Mas_HSN.UnitRate,Mas_HSN.NBPercL,Mas_HSN.NBPercH,X.EWaybillNo,x.EWaybilldt ,X.VName ,X.Transmode,X.Terms ')